function tests = testVision
%TESTVISION Synthetic tests for the base tag -> base frame pipeline (vision).
%   Tag corners are generated by projecting known tags through a known
%   camera, so every recovered position and yaw can be checked exactly.
%   Run:  addpath(genpath('vision')); runtests('tests')
    tests = functiontests(localfunctions);
end

function setupOnce(testCase)
    root = fileparts(fileparts(mfilename("fullpath")));
    addpath(genpath(fullfile(root, "vision")));
    testCase.TestData.layout = syntheticLayout(fullfile(root, "config", "layout.json"));
    testCase.TestData.pose = syntheticCamera();
end

% -------------------------------------------------------------------------
function testTagTargetFromBaseTagOnly(testCase)
    % Reach test: only the base tag and one other tag in the photo.
    layout = testCase.TestData.layout;
    truth = syntheticTruth(layout);
    tags = renderTags(truth, testCase.TestData.pose, layout, "ccw");
    result = solveTagTarget(tags, layout, testCase.TestData.pose.K, 99, 0);

    target = truth([truth.id] == 99);
    verifyEqual(testCase, result.target.UVW_mm, [target.centerUV_mm 0], AbsTol=1e-6);
    verifyEqual(testCase, result.target.yaw_deg, target.yaw_deg, AbsTol=1e-6);
    verifyEqual(testCase, result.target.phi_deg, atan2d(target.centerUV_mm(2), target.centerUV_mm(1)), AbsTol=1e-6);
    verifyLessThan(testCase, result.baseCheck.centerError_mm, 1e-6);
    verifyTrue(testCase, result.target.sideOk);
    verifyEmpty(testCase, result.warnings);

    verifyError(testCase, @() solveTagTarget(tags, layout, testCase.TestData.pose.K, 42, 0), "scene:tagNotSeen");
    verifyError(testCase, @() solveTagTarget(tags, layout, testCase.TestData.pose.K, layout.baseTag.id, 0), ...
        "tagTarget:sameTag");

    % The annotated image accepts the scene locateTagTarget builds.
    scene = struct("pose", result.pose, "tags", result.tags, ...
        "goal", struct("UVW_mm", result.target.UVW_mm, "label", "target 99"));
    img = drawScene(zeros(800, 1000, 3, "uint8"), scene, []);
    verifySize(testCase, img, [800 1000 3]);
end

function testMirroredWindingIsCaught(testCase)
    layout = testCase.TestData.layout;
    truth = syntheticTruth(layout);
    tags = renderTags(truth, testCase.TestData.pose, layout, "cw");    % layout says ccw
    verifyError(testCase, @() solveTagTarget(tags, layout, testCase.TestData.pose.K, 99, 0), ...
        "estimateTablePose:mirrored");
end

function testFindHomographyFourPointsExact(testCase)
    planeUV_mm = [0 0; 50 0; 50 50; 0 50];
    Htrue = [2 0.1 300; -0.05 1.9 200; 1e-4 2e-4 1];
    px = applyHomography(Htrue, planeUV_mm);
    [H, roundTripErr_mm] = findHomography(px, planeUV_mm);
    verifyEqual(testCase, H, Htrue, AbsTol=1e-9);
    verifyLessThan(testCase, max(roundTripErr_mm), 1e-9);
end

% -------------------------------------------------------------------------
function layout = syntheticLayout(layoutPath)
% The real layout.json with a base tag that is not axis-aligned, so yaw is exercised.
    layout = loadLayout(layoutPath);
    layout.tagSize_mm = 50;
    layout.tagCornerWinding = 'ccw';
    layout.baseTag = struct('id', 0, 'centerUV_mm', [0 -90], 'yaw_deg', 90, 'height_mm', 0);
end

function truth = syntheticTruth(layout)
% Where each tag really is (centre, yaw, height): the base tag and a target tag 99.
    truth = struct('id', {layout.baseTag.id, 99}, ...
        'centerUV_mm', {layout.baseTag.centerUV_mm, [0 250]}, ...
        'yaw_deg', {layout.baseTag.yaw_deg, 0}, ...
        'height_mm', {layout.baseTag.height_mm, 0});
end

function pose = syntheticCamera()
% Overhead camera, tilted ~12 deg, 650 mm above the plate.
    K = [2262.8 0 2835.1; 0 2261.5 2147.4; 0 0 1];       % close to the real calibration
    lookDown = [1 0 0; 0 -1 0; 0 0 -1];                   % camera x = +U, y = -V, z = -W
    tilt = [1 0 0; 0 cosd(12) -sind(12); 0 sind(12) cosd(12)] * ...
           [cosd(5) 0 sind(5); 0 1 0; -sind(5) 0 cosd(5)];
    R = tilt * lookDown;
    cameraCenter_mm = [30 -60 650];
    pose.K = K;
    pose.R = R;
    pose.t = -R * cameraCenter_mm.';
    pose.cameraCenter_mm = cameraCenter_mm;
end

function tags = renderTags(truth, pose, layout, winding, noise_px)
% Fake detectTags output: project each tag's corners through the camera.
    if nargin < 5
        noise_px = 0;
    end
    tags = struct('id', {}, 'cornerUV_px', {}, 'cornerUndist_px', {}, 'centerUV_px', {});
    for k = 1:numel(truth)
        corners_mm = tagCornersWorld(truth(k).centerUV_mm, truth(k).yaw_deg, layout.tagSize_mm, ...
            truth(k).height_mm, winding);
        px = projectWorldToPixel(pose, corners_mm) + noise_px * randn(4, 2);
        tags(end+1) = struct('id', truth(k).id, 'cornerUV_px', px, 'cornerUndist_px', px, ...
            'centerUV_px', mean(px, 1)); %#ok<AGROW>
    end
end
